                 WHERE s.account_id = gmail_message_facts.account_id
                   AND s.conversation_id = gmail_message_facts.conversation_id)
               AND NOT EXISTS (
                 SELECT 1 FROM gmail_operation_targets t
                 WHERE t.account_id = gmail_message_facts.account_id
